head.script:
// 테스트 설명, 유효성 값 설정
//  ★ iframe 컴포넌트는 oniframeload / oniframeunload 두 이벤트만 지원한다(engine iframe.js:357 userEvents).
//    onclick/onfocus 등은 iframe 컴포넌트 이벤트가 아니라 내부 문서로 흡수되어 미발생하므로 unbind 대상에서 제외.
//  · unbind 대상 이벤트는 oniframeload(내부 페이지 로드 완료 시 발생)를 기본으로 하고, oniframeunload(setSrc 재로드 직전 발생)도 지원.
//  · oniframeload 재발생 트리거 : target1.setSrc(url) 재호출(재로드). bind → 재로드로 발생 확인 → unbind → 재로드로 제거 여부를 결정적으로 확인한다.
//  · 사용자 정의 함수(scwin.comm_event : 고정 참조)는 bind 후 unbind 로 제거 가능 → 재로드 시 미발생.
//  · 익명 함수(eval 로 매번 새 함수 생성)는 bind 시 새 참조가 등록되고 unbind 는 다른 참조라 매칭 실패 → 제거 불가 → 재로드 시 여전히 발생.
//  · par_eventType 을 (생략), par_func 를 (생략)/undefined 로 두면 type/func 파라미터 생략·undefined 시의 전체 제거 동작을 검증할 수 있다.
scwin.tData = {
    "description" : "[iframe > M > unbind]<br/>컴포넌트의 특정 이벤트에서 이벤트 핸들러를 제거합니다.",
    "validation" : [
        "type 파라미터로 이벤트 핸들러를 제거할 이벤트의 이름을 문자열로 설정할 수 있어야 합니다.",
        "type 파라미터 생략 시 컴포넌트의 모든 이벤트에 등록된 핸들러 전체를 제거할 수 있어야 합니다.",
        "func 파라미터로 지정한 이벤트에서 제거할 이벤트 핸들러 함수를 설정할 수 있어야 합니다.",
        "func 파라미터 생략 시 지정한 이벤트에 등록된 핸들러 전체를 제거할 수 있어야 합니다.",
        "func 파라미터로 undefined 설정 시 지정한 이벤트에 등록된 핸들러 전체를 제거할 수 있어야 합니다.",
        "func 파라미터로 undefined 설정 시 func 파라미터값은 적용되지 않아야 합니다.",
        "익명 함수로 이벤트 핸들러를 등록한 경우 unbind() 메소드로 등록된 익명 함수를 제거할 수 없어야 합니다.",
        "사용자 정의 함수로 이벤트 핸들러를 등록한 경우 unbind() 메소드로 등록된 사용자 정의 함수를 제거할 수 있어야 합니다.",
        "이벤트 핸들러 함수가 중복으로 등록되어 있어도 해당 이벤트 핸들러 함수를 모두 제거할 수 있어야 합니다.",
        "이벤트 핸들러 함수 제거 후 남아 있는 이벤트 핸들러 함수의 순서는 유지되어야 합니다."
    ]
}


// 사용자 정의 함수 / 익명 함수 정의 문자열
//  - userFunc  : 'scwin.comm_event' → eval 시 항상 동일 함수 참조 반환 → unbind 로 제거 가능(validation 8)
//  - anonymFunc: 익명 함수 리터럴 → eval 마다 새 함수 생성 → unbind 매칭 실패 → 제거 불가(validation 7)
let userFunc = 'scwin.comm_event';
let anonymFunc = 'function(e){wf_body_bottom.getObj("scwin").setReturnValue("익명 함수호출");}';



scwin.onpageload = async function () {
    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - iframe 을 dynamicCreate 할 때 inline src 를 주면 _dynamicCreateAfter 가 미로딩 contentDocument 에 접근하여 TypeError 발생.
//    → src 없이 생성한 뒤 target1.setSrc() 로 내부 페이지를 설정한다. (reference_iframe_dynamic_setsrc_not_inline)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] iframe 컴포넌트는 oniframeload / oniframeunload 두 이벤트만 지원합니다. onclick/onfocus 등은 iframe 컴포넌트 이벤트가 아니라 내부 문서로 흡수되어 미발생하므로 unbind 대상에서 제외합니다.\n[절차] par_eventType(이벤트) / par_func(함수유형)을 선택하고 [bind] 로 핸들러를 등록한 뒤 [iframe 재로드(setSrc)] 로 발생을 확인합니다. 이어서 [unbind] 로 핸들러를 제거하고 다시 재로드하여 제거 여부를 확인합니다.\n[확인] 사용자 정의 함수(고정 참조)는 unbind 되어 재로드 시 미발생, 익명 함수(매번 새 참조)는 unbind 되지 않아 재로드 시 여전히 발생합니다. par_eventType 을 (생략)하면 unbind() 로 전체 제거, par_func 를 (생략)/undefined 로 두면 해당 이벤트의 핸들러 전체가 제거됩니다.\n※ 최초 로드의 oniframeload 는 bind 전에 지나가므로 반드시 bind/unbind 후 재로드 버튼으로 확인하십시오."', '', 'label1');

    // iframe 동적 생성 (inline src 금지)
    let strTarget = '';
    strTarget += '<w2:iframe ' + strNameSpace + ' scrolling="no" style="width:500px; height:200px; border:1px solid #cccccc;" id=""></w2:iframe>';
    scwin.target1 = await $p.dynamicCreate("target1", "iframe", strTarget, grp_comp);

    // 내부 페이지 설정 (생성 후 setSrc)
    target1.setSrc("/sample/common_link/iframe_link_1.xml");
}



// 사용자 정의 함수 (고정 참조) : unbind 로 제거 가능
scwin.comm_event = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("사용자 정의 함수호출");
};



// [bind 버튼] : par_eventType 이벤트에 par_func 유형의 핸들러를 등록 (unbind 시연 전제)
//  - 반복 클릭 시 동일 핸들러 중복 등록 가능(validation 9 중복 제거 확인용)
scwin.btn_bind_onclick = function (e) {
    let b = wf_body_bottom.getObj("scwin");
    let eventType = par_eventType.getValue();
    let pFunc = par_func.getText();
    if (eventType === '') {
        b.setReturnValue("bind 는 이벤트(par_eventType)를 선택해야 합니다.");
        return;
    }
    if (pFunc == "사용자정의함수") {
        target1.bind(eventType, eval('(' + userFunc + ')'));
        b.setReturnValue("bind(" + eventType + ", 사용자정의함수) 등록");
    } else if (pFunc == "익명함수") {
        target1.bind(eventType, eval('(' + anonymFunc + ')'));
        b.setReturnValue("bind(" + eventType + ", 익명함수) 등록");
    } else {
        b.setReturnValue("bind 는 사용자정의함수 또는 익명함수를 선택해야 합니다.");
    }
};



// [unbind 버튼] : par_eventType / par_func 조합에 따라 핸들러 제거 (common_M_unbind 로직 이식)
//  - type 지정 + func 지정 : 해당 이벤트에서 지정 함수만 제거(사용자정의=제거됨 / 익명=제거불가)
//  - type 지정 + func 생략 : 해당 이벤트의 핸들러 전체 제거
//  - type 지정 + func undefined : 해당 이벤트의 핸들러 전체 제거(func 값 미적용)
//  - type 생략 + func 지정 : 모든 이벤트에서 지정 함수 제거(target1.unbind(undefined, func))
//  - type 생략 + func 생략 : target1.unbind() → 모든 이벤트 핸들러 전체 제거
scwin.btn_unbind_onclick = function (e) {
    let b = wf_body_bottom.getObj("scwin");
    let pType = par_eventType.getValue();   // '' → type 생략
    let pFunc = par_func.getText();          // '' → func 생략, 'undefined' → func=undefined

    // func 인자 해석
    let funcArg;
    let hasFunc = (pFunc !== '');
    if (pFunc == "사용자정의함수") {
        funcArg = eval('(' + userFunc + ')');
    } else if (pFunc == "익명함수") {
        funcArg = eval('(' + anonymFunc + ')');
    } else if (pFunc == "undefined") {
        funcArg = undefined;
    }

    if (pType !== '' && hasFunc) {
        target1.unbind(pType, funcArg);
        b.setReturnValue("unbind(" + pType + ", " + pFunc + ") 호출");
    } else if (pType !== '' && !hasFunc) {
        target1.unbind(pType);
        b.setReturnValue("unbind(" + pType + ") 호출 → 해당 이벤트 핸들러 전체 제거");
    } else if (pType === '' && hasFunc) {
        target1.unbind(undefined, funcArg);
        b.setReturnValue("unbind(undefined, " + pFunc + ") 호출 → 모든 이벤트에서 지정 함수 제거");
    } else {
        target1.unbind();
        b.setReturnValue("unbind() 호출 → 모든 이벤트 핸들러 전체 제거");
    }
};



// [iframe 재로드(setSrc) 버튼] : 내부 페이지를 강제 재로드하여 oniframeload(재로드 직전 oniframeunload) 재발생
scwin.btn_reload_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("--- iframe 재로드(setSrc) ---");
    target1.setSrc("/sample/common_link/iframe_link_1.xml", true);
};
